W["javaa-p5-cf-combine"] = "\nimport java.util.concurrent.*;\n\npublic class Solution {\n    // WRONG: supplyAsync starts eagerly, but chaining with thenApply AFTER a\n    // blocking get() serializes the two supplies \u2014 defeating thenCombine\n    public static CompletableFuture<Integer> combined() {\n        try {\n            int a = CompletableFuture.supplyAsync(() -> 20).get();\n            int b = CompletableFuture.supplyAsync(() -> 22).get();\n            return CompletableFuture.completedFuture(a + b);\n        } catch (Exception e) { return CompletableFuture.completedFuture(-1); }\n    }\n\n    public static CompletableFuture<Integer> chained() {\n        return CompletableFuture.supplyAsync(() -> 3)\n            .thenCompose(x -> CompletableFuture.supplyAsync(() -> x * 2))\n            .thenApply(x -> x + 3);   // WRONG: +3 not +4\n    }\n\n    public static CompletableFuture<Integer> recovered() {\n        return CompletableFuture.<Integer>supplyAsync(() -> { throw new IllegalStateException(\"boom\"); });\n        // WRONG: no recovery \u2014 join() rethrows\n    }\n\n    public static CompletableFuture<Integer> bounded() {\n        return CompletableFuture.<Integer>supplyAsync(() -> 7);   // WRONG: no timeout\n    }\n}\n";
R["javaa-p5-vt-scale"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\n\npublic class Solution {\n    public static int vtFanout(int tasks) throws Exception {\n        AtomicInteger count = new AtomicInteger();\n        try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {\n            for (int i = 0; i < tasks; i++) {\n                exec.submit(() -> {\n                    Thread.sleep(20);\n                    count.incrementAndGet();\n                    return null;\n                });\n            }\n        }   // close() awaits everything\n        return count.get();\n    }\n\n    static volatile boolean virtualObserved = false;\n\n    public static boolean isVirtualInside() throws Exception {\n        Thread t = Thread.ofVirtual().start(() -> {\n            virtualObserved = Thread.currentThread().isVirtual();\n        });\n        t.join(5000);\n        return virtualObserved;\n    }\n\n    public static int platformParallelism() {\n        return Runtime.getRuntime().availableProcessors();\n    }\n\n    public static boolean virtualThreadsHelpCpuBound() { return false; }\n}\n";
W["javaa-p5-vt-scale"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.atomic.*;\n\npublic class Solution {\n    public static int vtFanout(int tasks) throws Exception {\n        AtomicInteger count = new AtomicInteger();\n        ExecutorService exec = Executors.newFixedThreadPool(10);   // WRONG: platform pool for\n        try {                                                       // 10k sleeping tasks\n            for (int i = 0; i < tasks; i++) {\n                exec.submit(() -> {\n                    Thread.sleep(20);\n                    count.incrementAndGet();\n                    return null;\n                });\n            }\n        } finally { exec.shutdown(); }\n        return count.get();\n    }\n\n    static volatile boolean virtualObserved = false;\n\n    public static boolean isVirtualInside() throws Exception {\n        Thread t = new Thread(() -> virtualObserved = Thread.currentThread().isVirtual()); // WRONG: platform\n        t.start(); t.join(5000);\n        return virtualObserved;\n    }\n\n    public static int platformParallelism() { return 0; }   // WRONG: not honest\n    public static boolean virtualThreadsHelpCpuBound() { return true; }   // WRONG: overclaims\n}\n";
R["javaa-p6-erasure"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static boolean sameErasure() {\n        return new ArrayList<String>().getClass() == new ArrayList<Integer>().getClass();\n    }\n\n    public static boolean arraysReified() {\n        Class<?> a = String[].class;   // via Class<?> \u2014 direct == on the literals is a\n        Class<?> b = Integer[].class;  // compile-time error: incomparable types\n        return a != b;\n    }\n\n    public static String classOfAList() {\n        return new ArrayList<String>().getClass().getName();\n    }\n\n    public static String arrayStore() {\n        try {\n            Object[] objs = new String[1];\n            objs[0] = 42;\n            return \"no error\";\n        } catch (ArrayStoreException e) {\n            return \"ArrayStoreException\";\n        }\n    }\n}\n";
W["javaa-p6-erasure"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static boolean sameErasure() {\n        return new ArrayList<String>().getClass() != new ArrayList<Integer>().getClass();  // WRONG: generics are erased\n    }\n\n    public static boolean arraysReified() {\n        Class<?> a = String[].class;\n        Class<?> b = Integer[].class;\n        return a == b;   // WRONG: compiles via Class<?> but is false at runtime\n    }\n\n    public static String classOfAList() {\n        return new ArrayList<String>().getClass().getSimpleName();   // WRONG: getName() expected\n    }\n\n    public static String arrayStore() {\n        try {\n            Object[] objs = new String[1];\n            objs[0] = 42;\n            return \"no error\";\n        } catch (ClassCastException e) {           // WRONG: the thrown type is ArrayStoreException\n            return \"ArrayStoreException\";\n        }\n    }\n}\n";
R["javaa-p6-copy-capture"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static <T> void copy(List<? extends T> src, List<? super T> dst) {\n        for (T t : src) dst.add(t);\n    }\n\n    public static void swap(List<?> list, int i, int j) {\n        swapHelper(list, i, j);\n    }\n\n    private static <E> void swapHelper(List<E> list, int i, int j) {\n        list.set(i, list.set(j, list.get(i)));\n    }\n}\n";
W["javaa-p6-copy-capture"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static <T> void copy(List<? extends T> src, List<? super T> dst) {\n        dst.clear();               // WRONG: destroys existing destination content\n        for (T t : src) dst.add(t);\n    }\n\n    public static void swap(List<?> list, int i, int j) {\n        // WRONG: no capture helper \u2014 this cannot compile against List<?> ...\n        // (kept compilable by casting through raw types, which erases the check)\n        List raw = list;\n        Object a = raw.get(i);\n        raw.set(i, raw.get(j));\n        raw.set(j, a);\n    }\n}\n";
R["javaa-p6-builder"] = "\nimport java.util.*;\n\npublic class Solution {\n    abstract static class Node<Self extends Node<Self>> {\n        private final List<String> labels = new ArrayList<>();\n\n        @SuppressWarnings(\"unchecked\")\n        public Self label(String l) {\n            labels.add(l);\n            return (Self) this;\n        }\n\n        String describeOf(String prefix) {\n            return prefix + labels;\n        }\n    }\n\n    public static class Task extends Node<Task> {\n        public String describe() { return describeOf(\"Task\"); }\n    }\n\n    public static class Job extends Node<Job> {\n        public String describe() { return describeOf(\"Job\"); }\n    }\n}\n";
W["javaa-p6-builder"] = "\nimport java.util.*;\n\npublic class Solution {\n    abstract static class Node<Self extends Node<Self>> {\n        private static final List<String> labels = new ArrayList<>();   // WRONG: static \u2014 shared by every instance\n\n        @SuppressWarnings(\"unchecked\")\n        public Self label(String l) {\n            labels.add(l);\n            return (Self) this;\n        }\n\n        String describeOf(String prefix) {\n            return prefix + labels;\n        }\n    }\n\n    public static class Task extends Node<Task> {\n        public String describe() { return describeOf(\"Task\"); }\n    }\n\n    public static class Job extends Node<Job> {\n        public String describe() { return describeOf(\"Job\"); }\n    }\n}\n";
R["javaa-p7-inspect"] = "\nimport java.lang.reflect.*;\n\npublic class Solution {\n    static class Widget {\n        private int a;\n        private String b;\n        public int c;\n    }\n\n    public static int declaredFieldCount() {\n        return Widget.class.getDeclaredFields().length;\n    }\n\n    public static int accessibleFieldCount() {\n        return Widget.class.getFields().length;\n    }\n\n    public static boolean knowsPrivate() {\n        for (Field f : Widget.class.getDeclaredFields()) {\n            if (f.getName().equals(\"a\")) return true;\n        }\n        return false;\n    }\n\n    public static String superName() {\n        return Widget.class.getSuperclass().getName();\n    }\n}\n";
W["javaa-p7-inspect"] = "\nimport java.lang.reflect.*;\n\npublic class Solution {\n    static class Widget {\n        private int a;\n        private String b;\n        public int c;\n    }\n\n    public static int declaredFieldCount() {\n        return Widget.class.getFields().length;       // WRONG: accessible inventory, not declared\n    }\n\n    public static int accessibleFieldCount() {\n        return Widget.class.getDeclaredFields().length;  // WRONG: swapped\n    }\n\n    public static boolean knowsPrivate() {\n        for (Field f : Widget.class.getFields()) {    // WRONG: searches the wrong inventory\n            if (f.getName().equals(\"a\")) return true;\n        }\n        return false;\n    }\n\n    public static String superName() {\n        return Widget.class.getName();                 // WRONG: self, not superclass\n    }\n}\n";
R["javaa-p7-dispatch"] = "\nimport java.lang.annotation.*;\nimport java.lang.reflect.*;\nimport java.util.*;\n\npublic class Solution {\n    @Retention(RetentionPolicy.RUNTIME)\n    @Target(ElementType.METHOD)\n    public @interface Route { String value(); }\n\n    @Route(\"/home\")\n    public static String serveHome() { return \"home-page\"; }\n\n    @Route(\"/about\")\n    public static String serveAbout() { return \"about-page\"; }\n\n    @Route(\"/help\")\n    public static String serveHelp() { return \"help-page\"; }\n\n    public static Map<String, String> routeTable() {\n        Map<String, String> table = new HashMap<>();\n        for (Method m : Solution.class.getDeclaredMethods()) {\n            Route r = m.getAnnotation(Route.class);\n            if (r != null) table.put(r.value(), m.getName());\n        }\n        return table;\n    }\n\n    public static String dispatch(String path, String body) {\n        String name = routeTable().get(path);\n        if (name == null) return \"404\";\n        try {\n            Method m = Solution.class.getDeclaredMethod(name);\n            return (String) m.invoke(null);\n        } catch (ReflectiveOperationException e) {\n            throw new IllegalStateException(e);\n        }\n    }\n}\n";
W["javaa-p7-dispatch"] = "\nimport java.lang.annotation.*;\nimport java.lang.reflect.*;\nimport java.util.*;\n\npublic class Solution {\n    @Retention(RetentionPolicy.RUNTIME)\n    @Target(ElementType.METHOD)\n    public @interface Route { String value(); }\n\n    @Route(\"/home\")\n    public static String serveHome() { return \"home-page\"; }\n\n    @Route(\"/about\")\n    public static String serveAbout() { return \"about-page\"; }\n\n    @Route(\"/help\")\n    public static String serveHelp() { return \"help-page\"; }\n\n    public static Map<String, String> routeTable() {\n        Map<String, String> table = new HashMap<>();\n        for (Method m : Solution.class.getDeclaredMethods()) {\n            if (m.getParameterCount() == 0 && m.getReturnType() == String.class) {\n                table.put(\"/\" + m.getName(), m.getName());   // WRONG: name-derived keys \u2014 /home maps to /serveHome\n            }\n        }\n        return table;\n    }\n\n    public static String dispatch(String path, String body) {\n        String name = routeTable().get(path);\n        if (name == null) return \"404\";\n        try {\n            Method m = Solution.class.getDeclaredMethod(name);\n            return (String) m.invoke(null);\n        } catch (ReflectiveOperationException e) {\n            throw new IllegalStateException(e);\n        }\n    }\n}\n";
R["javaa-p7-container-core"] = "\nimport java.lang.reflect.*;\nimport java.util.*;\n\npublic class Solution {\n    public static class Repo {\n        public String name() { return \"repo\"; }\n    }\n\n    public static class Service {\n        public final Repo repo;\n        public Service(Repo repo) { this.repo = repo; }\n    }\n\n    public static class Facade {\n        public final Service svc;\n        public Facade(Service svc) { this.svc = svc; }\n    }\n\n    public static class CycleA {\n        public CycleA(CycleB b) { }\n    }\n\n    public static class CycleB {\n        public CycleB(CycleA a) { }\n    }\n\n    public static class Container {\n        private final Map<Class<?>, Object> cache = new HashMap<>();\n        private final Set<Class<?>> inProgress = new HashSet<>();\n\n        @SuppressWarnings(\"unchecked\")\n        public <T> T resolve(Class<T> type) {\n            Object cached = cache.get(type);\n            if (cached != null) return type.cast(cached);\n            if (!inProgress.add(type)) {\n                throw new IllegalStateException(\"circular dependency resolving \" + type.getName());\n            }\n            try {\n                Constructor<?> ctor = type.getDeclaredConstructors()[0];\n                ctor.setAccessible(true);\n                Class<?>[] params = ctor.getParameterTypes();\n                Object[] args = new Object[params.length];\n                for (int i = 0; i < params.length; i++) {\n                    args[i] = resolve(params[i]);\n                }\n                T instance = type.cast(ctor.newInstance(args));\n                cache.put(type, instance);\n                return instance;\n            } catch (ReflectiveOperationException e) {\n                throw new IllegalStateException(\"cannot construct \" + type.getName(), e);\n            } finally {\n                inProgress.remove(type);\n            }\n        }\n    }\n}\n";
W["javaa-p7-container-core"] = "\nimport java.lang.reflect.*;\nimport java.util.*;\n\npublic class Solution {\n    public static class Repo {\n        public String name() { return \"repo\"; }\n    }\n\n    public static class Service {\n        public final Repo repo;\n        public Service(Repo repo) { this.repo = repo; }\n    }\n\n    public static class Facade {\n        public final Service svc;\n        public Facade(Service svc) { this.svc = svc; }\n    }\n\n    public static class CycleA {\n        public CycleA(CycleB b) { }\n    }\n\n    public static class CycleB {\n        public CycleB(CycleA a) { }\n    }\n\n    public static class Container {\n        private final Map<Class<?>, Object> cache = new HashMap<>();\n\n        @SuppressWarnings(\"unchecked\")\n        public <T> T resolve(Class<T> type) {\n            Object cached = cache.get(type);\n            if (cached != null) return type.cast(cached);\n            Constructor<?> ctor = type.getDeclaredConstructors()[0];\n            ctor.setAccessible(true);\n            Class<?>[] params = ctor.getParameterTypes();\n            Object[] args = new Object[params.length];\n            for (int i = 0; i < params.length; i++) {\n                args[i] = resolve(params[i]);   // WRONG: no in-progress set \u2014 A\u2192B\u2192A recurses forever\n            }\n            T instance = type.cast(ctor.newInstance());\n            cache.put(type, instance);\n            return instance;\n        }\n    }\n}\n";
R["javaa-p8-weakref"] = "\nimport java.lang.ref.*;\nimport java.util.*;\n\npublic class Solution {\n    static final List<Object> pinned = new ArrayList<>();\n\n    public static int retires() {\n        WeakReference<Object> w1 = new WeakReference<>(new Object());\n        WeakReference<Object> w2 = new WeakReference<>(new Object());\n        WeakReference<Object> w3 = new WeakReference<>(new Object());\n        System.gc();\n        System.gc();\n        int dead = 0;\n        for (WeakReference<Object> w : List.of(w1, w2, w3)) {\n            if (w.get() == null) dead++;\n        }\n        return dead;\n    }\n\n    public static int retiresWithStrong() {\n        WeakReference<Object> w1 = new WeakReference<>(new Object());\n        WeakReference<Object> w2 = new WeakReference<>(new Object());\n        WeakReference<Object> w3 = new WeakReference<>(new Object());\n        pinned.add(w1.get()); pinned.add(w2.get()); pinned.add(w3.get());\n        System.gc();\n        System.gc();\n        int dead = 0;\n        for (WeakReference<Object> w : List.of(w1, w2, w3)) {\n            if (w.get() == null) dead++;\n        }\n        return dead;\n    }\n\n    public static long heapAddress() {\n        Runtime rt = Runtime.getRuntime();\n        long usedBefore = rt.totalMemory() - rt.freeMemory();\n        int[] blob = new int[1_000_000];\n        blob[0] = blob.length;   // keep the array alive past the measurement\n        long usedAfter = rt.totalMemory() - rt.freeMemory();\n        if (blob[0] != blob.length) throw new AssertionError(\"unreachable\");\n        return usedAfter - usedBefore;\n    }\n}\n";
W["javaa-p8-weakref"] = "\nimport java.lang.ref.*;\nimport java.util.*;\n\npublic class Solution {\n    static final List<Object> pinned = new ArrayList<>();\n\n    public static int retires() {\n        WeakReference<Object> w1 = new WeakReference<>(new Object());\n        WeakReference<Object> w2 = new WeakReference<>(new Object());\n        WeakReference<Object> w3 = new WeakReference<>(new Object());\n        pinned.add(w1.get()); pinned.add(w2.get()); pinned.add(w3.get());  // WRONG: pins everything\n        System.gc();\n        System.gc();\n        int dead = 0;\n        for (WeakReference<Object> w : List.of(w1, w2, w3)) {\n            if (w.get() == null) dead++;\n        }\n        return dead;\n    }\n\n    public static int retiresWithStrong() {\n        WeakReference<Object> w1 = new WeakReference<>(new Object());\n        WeakReference<Object> w2 = new WeakReference<>(new Object());\n        WeakReference<Object> w3 = new WeakReference<>(new Object());\n        // WRONG: never pins \u2014 the \"strong\" scenario retires too\n        System.gc();\n        System.gc();\n        int dead = 0;\n        for (WeakReference<Object> w : List.of(w1, w2, w3)) {\n            if (w.get() == null) dead++;\n        }\n        return dead;\n    }\n\n    public static long heapAddress() {\n        return 0;   // WRONG: claims no memory cost\n    }\n}\n";
R["javaa-p8-identity"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static boolean smallBoxedIdentity() {\n        Integer a = 100;\n        Integer b = 100;\n        return a == b;\n    }\n\n    public static boolean largeBoxedIdentity() {\n        Integer a = 500;\n        Integer b = 500;\n        return a == b;\n    }\n\n    public static boolean largeBoxedEquals() {\n        Integer a = 500;\n        Integer b = 500;\n        return a.equals(b);\n    }\n\n    public static int sameIdentityTwice() {\n        List<String> one = new ArrayList<>();\n        int h1 = System.identityHashCode(one);\n        int h2 = System.identityHashCode(one);\n        return (h1 == h2) ? 1 : 2;\n    }\n}\n";
W["javaa-p8-identity"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static boolean smallBoxedIdentity() {\n        Integer a = 100;\n        Integer b = 100;\n        return !Objects.equals(a, b);   // WRONG: inverts the cache fact\n    }\n\n    public static boolean largeBoxedIdentity() {\n        Integer a = 500;\n        Integer b = 500;\n        return a == b;                  // WRONG: outside the cache \u2014 two allocations\n    }\n\n    public static boolean largeBoxedEquals() {\n        Integer a = 500;\n        Integer b = 500;\n        return a != b;                  // WRONG: equals is true\n    }\n\n    public static int sameIdentityTwice() {\n        List<String> one = new ArrayList<>();\n        int h1 = System.identityHashCode(one);\n        int h2 = System.identityHashCode(new ArrayList<>());   // WRONG: different object\n        return (h1 == h2) ? 1 : 2;\n    }\n}\n";
R["javaa-p8-cache"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class CacheKey {\n        final String id;\n        CacheKey(String id) { this.id = id; }\n    }\n\n    private static final WeakHashMap<CacheKey, String> store = new WeakHashMap<>();\n    private static final List<CacheKey> pinned = new ArrayList<>();\n\n    public static void put(CacheKey k, String v) {\n        store.put(k, v);\n    }\n\n    public static String get(CacheKey k) {\n        return store.get(k);\n    }\n\n    private static void seedWeak() {\n        // keys reachable only through the weak map after this returns\n        put(new CacheKey(\"a\"), \"va\");\n        put(new CacheKey(\"b\"), \"vb\");\n        put(new CacheKey(\"c\"), \"vc\");\n    }\n\n    private static void seedPinned() {\n        CacheKey a = new CacheKey(\"a\");\n        CacheKey b = new CacheKey(\"b\");\n        CacheKey c = new CacheKey(\"c\");\n        pinned.add(a); pinned.add(b); pinned.add(c);\n        put(a, \"va\"); put(b, \"vb\"); put(c, \"vc\");\n    }\n\n    public static int weakRetire() {\n        seedWeak();\n        // Weak refs are cleared by the GC but ENQUEUED asynchronously by the\n        // reference-processing thread \u2014 WeakHashMap sees the death a cycle later.\n        // Correctness must not depend on timing: bounded wait until drained.\n        for (int round = 0; round < 50 && store.size() > 0; round++) {\n            System.gc();\n            try { Thread.sleep(10); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        }\n        return store.size();   // size() expunges cleared entries\n    }\n\n    public static int strongRetire() {\n        seedPinned();\n        for (int round = 0; round < 5 && store.size() > 0; round++) {\n            System.gc();\n            try { Thread.sleep(10); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        }\n        return store.size();\n    }\n}\n";
W["javaa-p8-cache"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class CacheKey {\n        final String id;\n        CacheKey(String id) { this.id = id; }\n    }\n\n    private static final Map<CacheKey, String> store = new HashMap<>();   // WRONG: strong keys never die\n    private static final List<CacheKey> pinned = new ArrayList<>();\n\n    public static void put(CacheKey k, String v) {\n        store.put(k, v);\n    }\n\n    public static String get(CacheKey k) {\n        return store.get(k);\n    }\n\n    private static void seedWeak() {\n        put(new CacheKey(\"a\"), \"va\");\n        put(new CacheKey(\"b\"), \"vb\");\n        put(new CacheKey(\"c\"), \"vc\");\n    }\n\n    private static void seedPinned() {\n        CacheKey a = new CacheKey(\"a\");\n        CacheKey b = new CacheKey(\"b\");\n        CacheKey c = new CacheKey(\"c\");\n        pinned.add(a); pinned.add(b); pinned.add(c);\n        put(a, \"va\"); put(b, \"vb\"); put(c, \"vc\");\n    }\n\n    public static int weakRetire() {\n        seedWeak();\n        System.gc();   // WRONG: single shot, no wait for async reference enqueueing\n        return store.size();   // WRONG: 3 \u2014 the reference thread hasn't caught up (and a strong map never drops)\n    }\n\n    public static int strongRetire() {\n        seedPinned();\n        for (int round = 0; round < 5 && store.size() > 0; round++) {\n            System.gc();\n            try { Thread.sleep(10); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        }\n        return store.size();\n    }\n}\n";
R["javaa-p9-nano"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static long timedSum(int n) {\n        long t0 = System.nanoTime();\n        long sum = 0;\n        for (int i = 1; i <= n; i++) sum += i;\n        long elapsed = System.nanoTime() - t0;\n        if (sum != (long) n * (n + 1) / 2) {\n            throw new IllegalStateException(\"sum corrupted: \" + sum);\n        }\n        return elapsed;\n    }\n\n    public static long warmMedianSum(int n, int rounds) {\n        for (int w = 0; w < 2_000; w++) {\n            long s = 0;\n            for (int i = 1; i <= n; i++) s += i;\n            if (s == Long.MIN_VALUE) throw new IllegalStateException();\n        }\n        long[] samples = new long[rounds];\n        for (int r = 0; r < rounds; r++) {\n            samples[r] = timedSum(n) / 1_000;   // micros\n        }\n        Arrays.sort(samples);\n        return samples[rounds / 2];\n    }\n\n    public static boolean nanoIsMonotonic() {\n        long prev = System.nanoTime();\n        for (int i = 0; i < 1_000; i++) {\n            long now = System.nanoTime();\n            if (now < prev) return false;\n            prev = now;\n        }\n        return true;\n    }\n}\n";
W["javaa-p9-nano"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static long timedSum(int n) {\n        long t0 = System.nanoTime();\n        long sum = 0;\n        for (int i = 1; i <= n; i++) sum += i;   // result never checked:\n        return System.nanoTime() - t0;           // WRONG \u2014 the JIT may delete the whole loop\n    }\n\n    public static long warmMedianSum(int n, int rounds) {\n        long[] samples = new long[rounds];\n        for (int r = 0; r < rounds; r++) {\n            samples[r] = 0;                      // WRONG: never times \u2014 all zeros\n        }\n        Arrays.sort(samples);\n        return samples[rounds / 2];              // WRONG: median of nothing = 0\n    }\n\n    public static boolean nanoIsMonotonic() {\n        long prev = System.currentTimeMillis();  // WRONG: wall clock, not nanoTime\n        for (int i = 0; i < 1_000; i++) {\n            long now = System.nanoTime();\n            if (now < prev) return false;\n            prev = now;\n        }\n        return true;\n    }\n}\n";
R["javaa-p9-sortproof"] = "\npublic class Solution {\n    public static long inversionCount(int[] a) {\n        long inv = 0;\n        for (int i = 0; i < a.length; i++) {\n            for (int j = i + 1; j < a.length; j++) {\n                if (a[i] > a[j]) inv++;\n            }\n        }\n        return inv;\n    }\n\n    public static void bubbleSort(int[] a) {\n        for (int i = 0; i < a.length - 1; i++) {\n            for (int j = 0; j < a.length - 1 - i; j++) {\n                if (a[j] > a[j + 1]) {\n                    int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;\n                }\n            }\n        }\n    }\n\n    public static long swapsFor(int[] a) {\n        int[] copy = a.clone();\n        long swaps = 0;\n        for (int i = 0; i < copy.length - 1; i++) {\n            for (int j = 0; j < copy.length - 1 - i; j++) {\n                if (copy[j] > copy[j + 1]) {\n                    int t = copy[j]; copy[j] = copy[j + 1]; copy[j + 1] = t;\n                    swaps++;\n                }\n            }\n        }\n        return swaps;\n    }\n\n    public static boolean isSorted(int[] a) {\n        for (int i = 1; i < a.length; i++) {\n            if (a[i - 1] > a[i]) return false;\n        }\n        return true;\n    }\n}\n";
W["javaa-p9-sortproof"] = "\npublic class Solution {\n    public static long inversionCount(int[] a) {\n        long inv = 0;\n        for (int i = 0; i < a.length; i++) {\n            for (int j = i + 1; j < a.length; j++) {\n                if (a[i] > a[j]) inv++;\n            }\n        }\n        return inv;\n    }\n\n    public static void bubbleSort(int[] a) {\n        for (int i = 0; i < a.length - 1; i++) {\n            for (int j = 0; j < a.length - 1 - i; j++) {\n                if (a[j] > a[j + 1]) {\n                    int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;\n                }\n            }\n        }\n    }\n\n    public static long swapsFor(int[] a) {\n        return inversionCount(a) + 1;   // WRONG: +1 \u2014 swaps must EQUAL inversions\n    }\n\n    public static boolean isSorted(int[] a) {\n        for (int i = 1; i < a.length; i++) {\n            if (a[i - 1] >= a[i]) return false;   // WRONG: rejects equal neighbors \u2014 not non-decreasing\n        }\n        return true;\n    }\n}\n";
R["javaa-p10-path"] = "\nimport java.nio.file.*;\n\npublic class Solution {\n    public static Path buildLogPath(Path base) {\n        return base.resolve(\"logs\").resolve(\"app.log\");\n    }\n\n    public static String relativeShape(Path base, Path child) {\n        return base.relativize(child).toString();\n    }\n\n    public static int nameCount(Path p) {\n        return p.getNameCount();\n    }\n\n    public static boolean atomicSwap(Path src, Path dst) throws Exception {\n        Files.writeString(dst, \"old\");\n        Files.writeString(src, \"new\");\n        Files.move(src, dst, StandardCopyOption.REPLACE_EXISTING);\n        return Files.readString(dst).equals(\"new\") && !Files.exists(src);\n    }\n}\n";
