R["javaa-p10-walk"] = "\nimport java.nio.file.*;\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static List<String> findLogs(Path root) throws Exception {\n        try (Stream<Path> paths = Files.walk(root, 3)) {\n            return paths\n                .filter(Files::isRegularFile)\n                .map(p -> p.getFileName().toString())\n                .filter(n -> n.endsWith(\".log\"))\n                .sorted()\n                .collect(Collectors.toList());\n        }\n    }\n\n    public static long totalBytes(Path root) throws Exception {\n        try (Stream<Path> paths = Files.walk(root)) {\n            return paths\n                .filter(Files::isRegularFile)\n                .mapToLong(p -> {\n                    try { return Files.size(p); }\n                    catch (Exception e) { return 0L; }\n                })\n                .sum();\n        }\n    }\n\n    public static boolean globMatches(String pattern, Path candidate) {\n        return FileSystems.getDefault().getPathMatcher(\"glob:\" + pattern)\n            .matches(candidate);\n    }\n}\n";
W["javaa-p10-walk"] = "\nimport java.nio.file.*;\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static List<String> findLogs(Path root) throws Exception {\n        Stream<Path> paths = Files.walk(root, 3);        // WRONG: stream never closed (descriptor leak)\n        return paths\n            .map(p -> p.toString())                       // WRONG: full paths, not file names\n            .filter(p -> p.contains(\".log\"))\n            .collect(Collectors.toList());                // WRONG: unsorted, no depth/regular filter\n    }\n\n    public static long totalBytes(Path root) throws Exception {\n        return 0;                                         // WRONG: claims files are free\n    }\n\n    public static boolean globMatches(String pattern, Path candidate) {\n        return candidate.toString().contains(pattern.replace(\"*\", \"\"));  // WRONG: substring, not glob\n    }\n}\n";
R["javaa-p11-echo"] = "\nimport java.io.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\n\npublic class Solution {\n    public static String frame(String message) {\n        return message + \"\\n\";\n    }\n\n    public static List<String> deframe(String received) {\n        if (received.isEmpty()) return List.of();\n        boolean torn = !received.endsWith(\"\\n\");\n        String[] parts = received.split(\"\\n\", -1);\n        List<String> frames = new ArrayList<>();\n        int limit = torn ? parts.length - 1 : (parts[parts.length - 1].isEmpty() ? parts.length - 1 : parts.length);\n        for (int i = 0; i < limit; i++) {\n            if (!parts[i].isEmpty()) frames.add(parts[i]);\n        }\n        return frames;\n    }\n\n    public static byte[] lengthFrame(String payload) {\n        byte[] body = payload.getBytes(StandardCharsets.UTF_8);\n        byte[] framed = new byte[4 + body.length];\n        framed[0] = (byte) ((body.length >>> 24) & 0xFF);\n        framed[1] = (byte) ((body.length >>> 16) & 0xFF);\n        framed[2] = (byte) ((body.length >>> 8) & 0xFF);\n        framed[3] = (byte) (body.length & 0xFF);\n        System.arraycopy(body, 0, framed, 4, body.length);\n        return framed;\n    }\n\n    public static int prefixLength(byte[] framed) {\n        return ((framed[0] & 0xFF) << 24) | ((framed[1] & 0xFF) << 16)\n             | ((framed[2] & 0xFF) << 8)  | (framed[3] & 0xFF);\n    }\n}\n";
W["javaa-p11-echo"] = "\nimport java.io.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\n\npublic class Solution {\n    public static String frame(String message) {\n        return message;   // WRONG: no terminator \u2014 the reader can never frame it\n    }\n\n    public static List<String> deframe(String received) {\n        if (received.isEmpty()) return List.of();\n        return new ArrayList<>(List.of(received.split(\"\\n\")));   // WRONG: torn tail becomes a frame\n    }\n\n    public static byte[] lengthFrame(String payload) {\n        byte[] body = payload.getBytes(StandardCharsets.UTF_8);\n        byte[] framed = new byte[4 + body.length];\n        framed[0] = (byte) (body.length % 256);   // WRONG: only the low byte \u2014 truncates above 255\n        System.arraycopy(body, 0, framed, 4, body.length);\n        return framed;\n    }\n\n    public static int prefixLength(byte[] framed) {\n        return framed[0] & 0xFF;   // WRONG: reads one byte, not four\n    }\n}\n";
R["javaa-p11-timeout"] = "\nimport java.io.*;\nimport java.util.function.Supplier;\n\npublic class Solution {\n    public static int readWithBudget(Reader r, int budgetChars) throws Exception {\n        char[] buf = new char[budgetChars];\n        StringBuilder out = new StringBuilder();\n        int n;\n        while (out.length() < budgetChars && (n = r.read(buf, 0, budgetChars - out.length())) != -1) {\n            out.append(buf, 0, n);\n        }\n        return out.length();\n    }\n\n    public static long elapsedOf(Supplier<?> work) {\n        long t0 = System.nanoTime();\n        work.get();\n        return System.nanoTime() - t0;\n    }\n\n    public static String statusFor(long elapsedNanos, long deadlineNanos) {\n        return elapsedNanos <= deadlineNanos ? \"ok\" : \"timeout\";\n    }\n}\n";
W["javaa-p11-timeout"] = "\nimport java.io.*;\nimport java.util.function.Supplier;\n\npublic class Solution {\n    public static int readWithBudget(Reader r, int budgetChars) throws Exception {\n        int total = 0;\n        while (r.read() != -1) {   // WRONG: unbounded \u2014 ignores the budget entirely\n            total++;\n        }\n        return total;\n    }\n\n    public static long elapsedOf(Supplier<?> work) {\n        work.get();\n        return 0;   // WRONG: no measurement \u2014 the guard is decorative\n    }\n\n    public static String statusFor(long elapsedNanos, long deadlineNanos) {\n        return \"ok\";   // WRONG: deadlines never fire\n    }\n}\n";
R["javaa-p12-combinators"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public static final List<String> observations =\n        Collections.synchronizedList(new ArrayList<>());\n\n    public static CompletableFuture<String> recovered() {\n        return CompletableFuture.<String>supplyAsync(() -> {\n            throw new IllegalStateException(\"boom\");\n        }).exceptionally(e -> \"fallback\");\n    }\n\n    public static CompletableFuture<String> handled() {\n        return CompletableFuture.<String>supplyAsync(() -> {\n            throw new IllegalStateException(\"boom\");\n        }).handle((ok, err) -> err == null ? \"ok:\" + ok : \"fallback\");\n    }\n\n    public static CompletableFuture<String> observed() {\n        return CompletableFuture.supplyAsync(() -> \"value\")\n            .whenComplete((r, e) -> observations.add(\"saw-value\"));\n    }\n\n    public static CompletableFuture<String> onTimeoutFallback() {\n        return CompletableFuture.<String>supplyAsync(() -> {\n            try { Thread.sleep(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n            return \"late\";\n        }).completeOnTimeout(\"fast-fail\", 20, TimeUnit.MILLISECONDS);\n    }\n}\n";
W["javaa-p12-combinators"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public static final List<String> observations =\n        Collections.synchronizedList(new ArrayList<>());\n\n    public static CompletableFuture<String> recovered() {\n        return CompletableFuture.<String>supplyAsync(() -> {\n            throw new IllegalStateException(\"boom\");\n        }).whenComplete((r, e) -> { });   // WRONG: whenComplete observes but cannot recover\n    }\n\n    public static CompletableFuture<String> handled() {\n        return CompletableFuture.<String>supplyAsync(() -> {\n            throw new IllegalStateException(\"boom\");\n        }).handle((ok, err) -> err == null ? \"ok:\" + ok : err.getMessage());  // WRONG: leaks the message\n    }\n\n    public static CompletableFuture<String> observed() {\n        return CompletableFuture.supplyAsync(() -> \"value\")\n            .handle((r, e) -> { observations.add(\"saw-value\"); return \"REPLACED\"; });  // WRONG: handle replaces the value\n    }\n\n    public static CompletableFuture<String> onTimeoutFallback() {\n        return CompletableFuture.<String>supplyAsync(() -> \"late\")\n            .orTimeout(20, TimeUnit.MILLISECONDS);   // WRONG: orTimeout makes it EXCEPTIONAL, not a fallback value\n    }\n}\n";
R["javaa-p12-order"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static List<Integer> fanout(List<Integer> inputs, Executor executor) {\n        List<CompletableFuture<Integer>> futures = inputs.stream()\n            .map(i -> CompletableFuture.supplyAsync(() -> i * 2, executor))\n            .collect(Collectors.toList());\n        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();\n        return futures.stream().map(CompletableFuture::join).collect(Collectors.toList());\n    }\n\n    public static List<Integer> withFailures(List<Integer> inputs, Executor executor) {\n        List<CompletableFuture<Integer>> futures = inputs.stream()\n            .map(i -> CompletableFuture.<Integer>supplyAsync(() -> {\n                if (i % 2 == 1) throw new IllegalStateException(\"odd\");\n                return i * 2;\n            }, executor).handle((r, e) -> e == null ? r : -1))\n            .collect(Collectors.toList());\n        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();\n        return futures.stream().map(CompletableFuture::join).collect(Collectors.toList());\n    }\n}\n";
W["javaa-p12-order"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static List<Integer> fanout(List<Integer> inputs, Executor executor) {\n        List<CompletableFuture<Integer>> futures = inputs.stream()\n            .map(i -> CompletableFuture.supplyAsync(() -> i * 2, executor))\n            .collect(Collectors.toList());\n        return futures.stream()\n            .map(f -> f.join())\n            .collect(Collectors.toList());   // WRONG: joins without allOf is fine for order,\n    }                                        // but no aggregate bound \u2014 see withFailures\n\n    public static List<Integer> withFailures(List<Integer> inputs, Executor executor) {\n        List<CompletableFuture<Integer>> futures = inputs.stream()\n            .map(i -> CompletableFuture.<Integer>supplyAsync(() -> {\n                if (i % 2 == 1) throw new IllegalStateException(\"odd\");\n                return i * 2;\n            }, executor))                 // WRONG: no per-branch recovery \u2014 the first odd id\n            .collect(Collectors.toList()); // rethrows at join and the whole fan-out collapses\n        return futures.stream()\n            .map(CompletableFuture::join)\n            .collect(Collectors.toList());\n    }\n}\n";
R["javaa-p13-traversal"] = "\nimport java.nio.file.*;\nimport java.util.*;\n\npublic class Solution {\n    public static boolean contained(Path root, String userPath) {\n        Path base = root.toAbsolutePath().normalize();\n        Path target = base.resolve(userPath).normalize();\n        return target.startsWith(base);\n    }\n\n    public static boolean allowsHost(String host, Set<String> allowlist) {\n        return allowlist.contains(host.toLowerCase());\n    }\n\n    public static String classifyUrl(String url, Set<String> allowlist) {\n        int schemeEnd = url.indexOf(\"://\");\n        if (schemeEnd < 0) return \"blocked\";\n        int hostStart = schemeEnd + 3;\n        int slash = url.indexOf('/', hostStart);\n        String host = (slash < 0 ? url.substring(hostStart) : url.substring(hostStart, slash))\n            .toLowerCase();\n        return allowsHost(host, allowlist) ? \"allowed\" : \"blocked\";\n    }\n}\n";
