R["javaa-checkpoint-m2-task"] = "\nimport java.util.*;\n\npublic class Solution {\n    static final List<String> trace = new ArrayList<>();\n\n    public static class Probe {\n        static { trace.add(\"probe<clinit>\"); }               // Probe writes into Solution-owned state\n    }\n\n    public static String evidence() throws Exception {\n        Class<?> silent = Probe.class;                       // no <clinit>\n        boolean litSilent = trace.isEmpty();\n        Class.forName(\"Solution$Probe\");                     // <clinit> runs\n        boolean forNameLoud = trace.contains(\"probe<clinit>\");\n        String pool = (\"jvm\" == new String(\"jvm\").intern()) ? \"pool-true\" : \"pool-false\";\n        return \"literal-silent:\" + litSilent + \";forName-loud:\" + forNameLoud + \";\" + pool;\n    }\n}\n";
W["javaa-checkpoint-m2-task"] = "\nimport java.util.*;\n\npublic class Solution {\n    public static class Probe {\n        static final List<String> LOG = new ArrayList<>();\n        static { LOG.add(\"probe<clinit>\"); }\n    }\n\n    static final List<String> trace = new ArrayList<>();\n\n    public static class Probe {\n        static { trace.add(\"probe<clinit>\"); }\n    }\n\n    public static String evidence() throws Exception {\n        // WRONG: never actively uses Probe (so <clinit> never runs), and the\n        // intern comparison is against a fresh heap object\n        Class<?> silent = Probe.class;\n        boolean litSilent = trace.isEmpty();\n        Class<?> alsoSilent = Probe.class;\n        boolean forNameLoud = trace.contains(\"probe<clinit>\");   // always false now\n        String pool = (\"jvm\" == new String(\"jvm\")) ? \"pool-true\" : \"pool-false\";  // fresh object != literal\n        return \"literal-silent:\" + litSilent + \";forName-loud:\" + forNameLoud + \";\" + pool;\n    }\n}\n";
R["javaa-checkpoint-m3-task"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    static boolean run = true;\n\n    public static List<String> audit() throws Exception {\n        List<String> mainLog = new ArrayList<>();\n        List<String> workerLog = new CopyOnWriteArrayList<>();\n        var q = new SynchronousQueue<List<String>>();\n        var ready = new CountDownLatch(1);\n        var done = new CountDownLatch(1);\n\n        run = true;\n        Thread worker = Thread.ofVirtual().start(() -> {\n            workerLog.add(\"worker-started\");\n            try {\n                ready.countDown();\n                q.put(List.of(\"v1\", \"v2\"));\n                done.await();                    // hb edge: done.await after main's countDown\n                workerLog.add(\"run-seen:\" + run);\n                workerLog.add(\"worker-done\");\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n\n        ready.await();                           // hb edge: everything after sees before\n        List<String> payload = q.take();         // hb edge: take after put\n        mainLog.add(\"taken:\" + payload);\n        run = false;\n        done.countDown();                        // hb edge: write then signal\n        worker.join(5000);\n        List<String> out = new ArrayList<>(mainLog);\n        out.addAll(workerLog);\n        return List.copyOf(out);\n    }\n}\n";
W["javaa-checkpoint-m3-task"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    static boolean run = true;\n\n    public static List<String> audit() throws Exception {\n        List<String> mainLog = new ArrayList<>();\n        List<String> workerLog = new CopyOnWriteArrayList<>();\n        var q = new SynchronousQueue<List<String>>();\n        var ready = new CountDownLatch(1);\n        var done = new CountDownLatch(1);\n\n        run = true;\n        Thread worker = Thread.ofVirtual().start(() -> {\n            workerLog.add(\"worker-started\");\n            try {\n                ready.countDown();\n                q.put(List.of(\"v1\", \"v2\"));\n                // WRONG: no done.await() \u2014 the worker's read of `run` has no\n                // hb edge from the main thread's write, the exact audit failure\n                workerLog.add(\"run-seen:\" + run);\n                workerLog.add(\"worker-done\");\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n\n        ready.await();\n        List<String> payload = q.take();\n        mainLog.add(\"taken:\" + payload);\n        run = false;\n        done.countDown();\n        worker.join(5000);\n        List<String> out = new ArrayList<>(mainLog);\n        out.addAll(workerLog);\n        return List.copyOf(out);\n    }\n}\n";
R["javaa-checkpoint-m4-task"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.locks.*;\n\npublic class Solution {\n    public static List<Integer> runBuffer() throws Exception {\n        ReentrantLock lock = new ReentrantLock();\n        Condition notFull = lock.newCondition();\n        Condition notEmpty = lock.newCondition();\n        ArrayDeque<Integer> buf = new ArrayDeque<>();\n        final int CAP = 2;\n\n        CountDownLatch consumerDone = new CountDownLatch(5);\n        CopyOnWriteArrayList<Integer> out = new CopyOnWriteArrayList<>();\n\n        Thread producer = Thread.ofVirtual().start(() -> {\n            try {\n                for (int i = 1; i <= 5; i++) {\n                    lock.lock();\n                    try {\n                        while (buf.size() == CAP) notFull.await();\n                        buf.addLast(i);\n                        notEmpty.signal();\n                    } finally { lock.unlock(); }\n                }\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n\n        Thread consumer = Thread.ofVirtual().start(() -> {\n            try {\n                for (int i = 0; i < 5; i++) {\n                    lock.lock();\n                    try {\n                        while (buf.isEmpty()) notEmpty.await();\n                        out.add(buf.removeFirst());\n                        notFull.signal();\n                        consumerDone.countDown();\n                    } finally { lock.unlock(); }\n                }\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n\n        producer.join(10_000);\n        consumerDone.await(10, TimeUnit.SECONDS);\n        consumer.join(10_000);\n        return List.copyOf(out);\n    }\n\n    public static String casAlternative() {\n        return \"a CAS loop on an index pair could do it, but Condition queues express the wait logic more clearly\";\n    }\n}\n";
W["javaa-checkpoint-m4-task"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.concurrent.locks.*;\n\npublic class Solution {\n    public static List<Integer> runBuffer() throws Exception {\n        ReentrantLock lock = new ReentrantLock();\n        Condition notFull = lock.newCondition();\n        Condition notEmpty = lock.newCondition();\n        ArrayDeque<Integer> buf = new ArrayDeque<>();\n        final int CAP = 2;\n\n        CountDownLatch consumerDone = new CountDownLatch(5);\n        CopyOnWriteArrayList<Integer> out = new CopyOnWriteArrayList<>();\n\n        Thread producer = Thread.ofVirtual().start(() -> {\n            try {\n                for (int i = 1; i <= 5; i++) {\n                    lock.lock();\n                    try {\n                        if (buf.size() == CAP) notFull.await();   // WRONG: `if` not `while`\n                        buf.addLast(i);\n                        notEmpty.signal();\n                    } finally { lock.unlock(); }\n                }\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n\n        Thread consumer = Thread.ofVirtual().start(() -> {\n            try {\n                for (int i = 0; i < 5; i++) {\n                    lock.lock();\n                    try {\n                        if (buf.isEmpty()) notEmpty.await();      // WRONG: `if` not `while`\n                        out.add(buf.removeFirst());\n                        notFull.signal();\n                        consumerDone.countDown();\n                    } finally { lock.unlock(); }\n                }\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n\n        producer.join(10_000);\n        consumerDone.await(10, TimeUnit.SECONDS);\n        consumer.join(10_000);\n        return List.copyOf(out);\n    }\n\n    public static String casAlternative() {\n        return \"CAS is always better\";   // WRONG: overclaims\n    }\n}\n";
R["javaa-checkpoint-m5-task"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public static List<String> aggregate(int shards) throws Exception {\n        List<String> out = new ArrayList<>();\n        try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {\n            List<CompletableFuture<String>> futs = new ArrayList<>();\n            for (int i = 0; i < shards; i++) {\n                final int shard = i;\n                futs.add(CompletableFuture.supplyAsync(() -> {\n                    try { Thread.sleep(10); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n                    if (shard % 2 == 1) throw new IllegalStateException(\"shard \" + shard + \" down\");\n                    return \"shard-\" + shard + \"-ok\";\n                }, exec).exceptionally(e -> \"shard-\" + shard + \"-failed\"));\n            }\n            for (CompletableFuture<String> f : futs) out.add(f.join());\n        }\n        return List.copyOf(out);\n    }\n\n    public static String executorChoice() {\n        return \"virtual threads per task: blocking work scales, CPU work still capped by cores\";\n    }\n}\n";
W["javaa-checkpoint-m5-task"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\n\npublic class Solution {\n    public static List<String> aggregate(int shards) throws Exception {\n        List<String> out = new ArrayList<>();\n        ExecutorService exec = Executors.newFixedThreadPool(2);\n        try {\n            List<CompletableFuture<String>> futs = new ArrayList<>();\n            for (int i = 0; i < shards; i++) {\n                final int shard = i;\n                futs.add(CompletableFuture.supplyAsync(() -> {\n                    try { Thread.sleep(10); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n                    return \"shard-\" + shard + \"-ok\";           // WRONG: failures never mapped\n                }, exec));\n            }\n            for (CompletableFuture<String> f : futs) out.add(f.join());   // throws on odd shards\n        } finally { exec.shutdown(); }\n        return List.copyOf(out);\n    }\n\n    public static String executorChoice() {\n        return \"more pool threads always helps\";   // WRONG: false for CPU-bound\n    }\n}\n";
