R["javaa-checkpoint-m10-task"] = "\nimport java.nio.file.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\n\npublic class Solution {\n    public static Path append(Path file, String event) throws Exception {\n        Files.writeString(file, event + \"\\n\", StandardCharsets.UTF_8,\n            StandardOpenOption.CREATE, StandardOpenOption.APPEND);\n        return file;\n    }\n\n    public static List<String> replay(Path file) throws Exception {\n        String raw = Files.readString(file, StandardCharsets.UTF_8);\n        if (raw.isEmpty()) return List.of();\n        boolean torn = !raw.endsWith(\"\\n\");\n        String[] lines = raw.split(\"\\n\", -1);\n        List<String> out = new ArrayList<>();\n        int limit = lines.length - (torn ? 1 : 0) - (raw.endsWith(\"\\n\") && lines.length > 0 && lines[lines.length - 1].isEmpty() ? 1 : 0);\n        for (int i = 0; i < limit; i++) {\n            if (!lines[i].isEmpty()) out.add(lines[i]);\n        }\n        return out;\n    }\n\n    public static int countEvents(Path file) throws Exception {\n        return replay(file).size();\n    }\n\n    public static Path rotate(Path file, int maxLines) throws Exception {\n        if (countEvents(file) <= maxLines) return file;\n        Path archive = file.resolveSibling(file.getFileName().toString() + \".1\");\n        Files.move(file, archive, StandardCopyOption.REPLACE_EXISTING,\n            StandardCopyOption.ATOMIC_MOVE);\n        Files.createFile(file);\n        return archive;\n    }\n}\n";
W["javaa-checkpoint-m10-task"] = "\nimport java.nio.file.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\n\npublic class Solution {\n    public static Path append(Path file, String event) throws Exception {\n        Files.writeString(file, event + \"\\n\", StandardCharsets.UTF_8,\n            CREATE, APPEND);\n        return file;\n    }\n\n    public static List<String> replay(Path file) throws Exception {\n        String raw = Files.readString(file, StandardCharsets.UTF_8);\n        if (raw.isEmpty()) return List.of();\n        return new ArrayList<>(List.of(raw.split(\"\\n\")));   // WRONG: torn tail becomes an \"event\"\n    }\n\n    public static int countEvents(Path file) throws Exception {\n        return replay(file).size();\n    }\n\n    public static Path rotate(Path file, int maxLines) throws Exception {\n        if (countEvents(file) <= maxLines) return file;\n        Path archive = file.resolveSibling(file.getFileName().toString() + \".1\");\n        Files.write(archive, Files.readAllBytes(file));   // WRONG: copy, then delete \u2014\n        Files.delete(file);                                // a non-atomic window where history exists twice or not at all\n        Files.createFile(file);\n        return archive;\n    }\n}\n";
R["javaa-checkpoint-m11-task"] = "\nimport java.io.*;\nimport java.net.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\n\npublic class Solution {\n    public static String handle(String line, Map<String, String> store) {\n        if (line == null) return \"ERR\";\n        String trimmed = line.trim();\n        if (trimmed.isEmpty()) return \"ERR\";\n        if (trimmed.equals(\"QUIT\")) return \"BYE\";\n        String[] parts = trimmed.split(\" \", 3);\n        String cmd = parts[0];\n        if (cmd.equals(\"PUT\") && parts.length == 3) {\n            store.put(parts[1], parts[2]);\n            return \"OK\";\n        }\n        if (cmd.equals(\"GET\") && parts.length == 2) {\n            String v = store.get(parts[1]);\n            return v == null ? \"MISSING\" : \"VALUE \" + v;\n        }\n        return \"ERR\";\n    }\n\n    public static int serveOnce(int port) throws Exception {\n        int turns = 0;\n        try (ServerSocket server = new ServerSocket(port)) {\n            server.setSoTimeout(10_000);\n            try (Socket client = server.accept()) {\n                client.setSoTimeout(5_000);\n                BufferedReader in = new BufferedReader(\n                    new InputStreamReader(client.getInputStream(), StandardCharsets.UTF_8));\n                PrintWriter out = new PrintWriter(\n                    new OutputStreamWriter(client.getOutputStream(), StandardCharsets.UTF_8), true);\n                Map<String, String> store = new HashMap<>();\n                String line;\n                boolean done = false;\n                while (!done && (line = in.readLine()) != null) {\n                    String response = handle(line, store);\n                    turns++;\n                    out.println(response);\n                    if (response.equals(\"BYE\")) done = true;\n                }\n            }\n        }\n        return turns;\n    }\n}\n";
W["javaa-checkpoint-m11-task"] = "\nimport java.io.*;\nimport java.net.*;\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\n\npublic class Solution {\n    public static String handle(String line, Map<String, String> store) {\n        if (line == null) return \"ERR\";\n        String trimmed = line.trim();\n        if (trimmed.isEmpty()) return \"ERR\";\n        if (trimmed.equals(\"QUIT\")) return \"BYE\";\n        String[] parts = trimmed.split(\" \", 2);   // WRONG: splits into 2 \u2014 PUT loses multi-word values\n        String cmd = parts[0];\n        if (cmd.equals(\"PUT\") && parts.length == 2) {\n            String[] kv = parts[1].split(\" \", 2);\n            store.put(kv[0], kv.length > 1 ? kv[1] : \"\");\n            return \"OK\";\n        }\n        if (cmd.equals(\"GET\")) {\n            String key = trimmed.substring(3).trim();\n            String v = store.get(key);\n            return v == null ? \"MISSING\" : \"VALUE \" + v;\n        }\n        return \"OK\";   // WRONG: unknown commands answer OK instead of ERR\n    }\n\n    public static int serveOnce(int port) throws Exception {\n        int turns = 0;\n        try (ServerSocket server = new ServerSocket(port)) {\n            try (Socket client = server.accept()) {\n                // WRONG: no soTimeout \u2014 a wedged client hangs the run forever\n                BufferedReader in = new BufferedReader(\n                    new InputStreamReader(client.getInputStream(), StandardCharsets.UTF_8));\n                PrintWriter out = new PrintWriter(\n                    new OutputStreamWriter(client.getOutputStream(), StandardCharsets.UTF_8), true);\n                Map<String, String> store = new HashMap<>();\n                String line;\n                while ((line = in.readLine()) != null) {   // WRONG: never stops at BYE\n                    turns++;\n                    out.println(handle(line, store));\n                }\n            }\n        }\n        return turns;\n    }\n}\n";
R["javaa-checkpoint-m12-task"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static List<String> aggregate(List<Integer> ids, Executor executor) {\n        List<CompletableFuture<String>> branches = ids.stream()\n            .map(id -> CompletableFuture.<String>supplyAsync(() -> {\n                try { Thread.sleep(id); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n                if (id % 2 == 1) throw new IllegalStateException(\"odd \" + id);\n                return \"id-\" + id + \"-ok\";\n            }, executor)\n                .orTimeout(80, TimeUnit.MILLISECONDS)\n                .handle((r, e) -> {\n                    if (e == null) return r;\n                    Throwable ex = e;\n                    if (ex instanceof CompletionException && ex.getCause() != null) {\n                        ex = ex.getCause();   // task failures arrive wrapped; orTimeout is raw\n                    }\n                    return (ex instanceof TimeoutException)\n                        ? \"id-\" + id + \"-timeout\"\n                        : \"id-\" + id + \"-error\";\n                }))\n            .collect(Collectors.toList());\n        try {\n            CompletableFuture.allOf(branches.toArray(new CompletableFuture[0]))\n                .orTimeout(500, TimeUnit.MILLISECONDS).join();\n        } catch (CompletionException e) {\n            // aggregate bound tripped: leave entries as their handled state\n        }\n        return branches.stream().map(f -> {\n            try { return f.join(); }\n            catch (CompletionException e) { return \"id-?-error\"; }\n        }).collect(Collectors.toList());\n    }\n\n    public static String philosophy() {\n        return \"per-branch bounds degrade dependencies; the aggregate bound protects the caller;\\nfailures are values\";\n    }\n}\n";
W["javaa-checkpoint-m12-task"] = "\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static List<String> aggregate(List<Integer> ids, Executor executor) {\n        List<CompletableFuture<String>> branches = ids.stream()\n            .map(id -> CompletableFuture.<String>supplyAsync(() -> {\n                try { Thread.sleep(id); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n                if (id % 2 == 1) throw new IllegalStateException(\"odd \" + id);\n                return \"id-\" + id + \"-ok\";\n            }, executor)\n                .orTimeout(80, TimeUnit.MILLISECONDS)\n                .exceptionally(e -> \"id-\" + id + \"-failed\"))   // WRONG: one generic label \u2014 timeout vs error lost\n            .collect(Collectors.toList());\n        return branches.stream()\n            .map(f -> f.join())\n            .collect(Collectors.toList());   // WRONG: no aggregate bound at all\n    }\n\n    public static String philosophy() {\n        return \"timeouts propagate; callers race their own deadlines\";   // WRONG: the anti-contract\n    }\n}\n";
R["javaa-checkpoint-m13-task"] = "\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Path;\nimport java.security.MessageDigest;\nimport java.security.SecureRandom;\nimport java.util.*;\n\npublic class Solution {\n    public static class Fw {\n        public final Path root;\n        public final Set<String> allowedHosts;\n\n        public Fw(Path root, Set<String> allowedHosts) {\n            this.root = root;\n            this.allowedHosts = allowedHosts;\n        }\n\n        public boolean canRead(String userPath) {\n            Path base = root.toAbsolutePath().normalize();\n            Path target = base.resolve(userPath).normalize();\n            return target.startsWith(base);\n        }\n\n        public boolean canCall(String url) {\n            int schemeEnd = url.indexOf(\"://\");\n            if (schemeEnd < 0) return false;\n            int hostStart = schemeEnd + 3;\n            int slash = url.indexOf('/', hostStart);\n            String host = (slash < 0 ? url.substring(hostStart) : url.substring(hostStart, slash))\n                .toLowerCase();\n            return allowedHosts.contains(host);\n        }\n\n        public boolean authenticate(byte[] salt, String password, byte[] stored) {\n            return MessageDigest.isEqual(hash(salt, password), stored);\n        }\n\n        public static byte[] salt() {\n            byte[] s = new byte[16];\n            new SecureRandom().nextBytes(s);\n            return s;\n        }\n\n        public static byte[] hash(byte[] salt, String password) {\n            try {\n                MessageDigest md = MessageDigest.getInstance(\"SHA-256\");\n                md.update(salt);\n                md.update(password.getBytes(StandardCharsets.UTF_8));\n                return md.digest();\n            } catch (Exception e) {\n                throw new IllegalStateException(e);\n            }\n        }\n\n        public static String review(Map<String, String> findings) {\n            Map<String, Set<String>> accepted = Map.of(\n                \"sql\", Set.of(\"parameterized\"),\n                \"secret\", Set.of(\"env\"),\n                \"depends\", Set.of(\"audited\"));\n            for (Map.Entry<String, String> e : findings.entrySet()) {\n                Set<String> ok = accepted.get(e.getKey());\n                if (ok == null || !ok.contains(e.getValue())) return e.getKey();\n            }\n            return \"pass\";\n        }\n\n        public static String threatOf(String control) {\n            return switch (control) {\n                case \"canonicalization\", \"parameterized\" -> \"T\";\n                case \"allowlist\" -> \"I\";\n                case \"least-privilege\" -> \"E\";\n                case \"rate-limit\" -> \"D\";\n                default -> \"?\";\n            };\n        }\n    }\n}\n";
W["javaa-checkpoint-m13-task"] = "\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Path;\nimport java.security.MessageDigest;\nimport java.util.*;\n\npublic class Solution {\n    public static class Fw {\n        public final Path root;\n        public final Set<String> allowedHosts;\n\n        public Fw(Path root, Set<String> allowedHosts) {\n            this.root = root;\n            this.allowedHosts = allowedHosts;\n        }\n\n        public boolean canRead(String userPath) {\n            return !userPath.contains(\"..\");   // WRONG: raw-string filter, not containment\n        }\n\n        public boolean canCall(String url) {\n            return url.contains(\"api.example.com\");   // WRONG: substring allowlist\n        }\n\n        public boolean authenticate(byte[] salt, String password, byte[] stored) {\n            try {\n                MessageDigest md = MessageDigest.getInstance(\"SHA-256\");\n                md.update(password.getBytes(StandardCharsets.UTF_8));   // WRONG: salt ignored\n                return Arrays.equals(md.digest(), stored);              // WRONG: early-exit compare\n            } catch (Exception e) {\n                throw new IllegalStateException(e);\n            }\n        }\n\n        public static byte[] salt() { return new byte[16]; }   // WRONG: zeros\n\n        public static byte[] hash(byte[] salt, String password) {\n            try {\n                MessageDigest md = MessageDigest.getInstance(\"SHA-256\");\n                md.update(password.getBytes(StandardCharsets.UTF_8));\n                return md.digest();\n            } catch (Exception e) { throw new IllegalStateException(e); }\n        }\n\n        public static String review(Map<String, String> findings) {\n            return \"pass\";   // WRONG: review approves everything\n        }\n\n        public static String threatOf(String control) {\n            return \"?\";   // WRONG: no STRIDE mapping\n        }\n    }\n}\n";
R["javaa-checkpoint-m14-task"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static class Ev {\n        public final long ts;\n        public final String level, event, requestId, endpoint;\n        public Ev(long ts, String level, String event, String requestId, String endpoint) {\n            this.ts = ts; this.level = level; this.event = event;\n            this.requestId = requestId; this.endpoint = endpoint;\n        }\n    }\n\n    public static List<String> affectedRequests(List<Ev> events) {\n        Set<String> seen = new LinkedHashSet<>();\n        for (Ev e : events) {\n            if (e.level.equals(\"ERROR\")) seen.add(e.requestId);\n        }\n        return new ArrayList<>(seen);\n    }\n\n    public static Map<String, Long> byEndpoint(List<Ev> events) {\n        return events.stream()\n            .filter(e -> e.level.equals(\"ERROR\"))\n            .collect(Collectors.groupingBy(e -> e.endpoint, Collectors.counting()));\n    }\n\n    public static List<String> cascadeOf(List<Ev> events, String requestId) {\n        return events.stream()\n            .filter(e -> e.requestId.equals(requestId))\n            .sorted(Comparator.comparingLong(e -> e.ts))\n            .map(e -> e.event)\n            .collect(Collectors.toList());\n    }\n\n    public static String verdict(List<Ev> events) {\n        List<String> affected = affectedRequests(events);\n        Map<String, Long> byEp = byEndpoint(events);\n        if (affected.size() == 1) return \"isolated\";\n        if (byEp.size() == 1 && affected.size() >= 2) return \"endpoint-outage\";\n        return \"widespread\";\n    }\n\n    public static String refutes(String hypothesis) {\n        return switch (hypothesis) {\n            case \"endpoint-outage\" -> \"an error on a different endpoint\";\n            case \"isolated\" -> \"a second affected request\";\n            case \"widespread\" -> \"errors stop after deploy\";\n            default -> \"no refuter defined\";\n        };\n    }\n}\n";
W["javaa-checkpoint-m14-task"] = "\nimport java.util.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public static class Ev {\n        public final long ts;\n        public final String level, event, requestId, endpoint;\n        public Ev(long ts, String level, String event, String requestId, String endpoint) {\n            this.ts = ts; this.level = level; this.event = event;\n            this.requestId = requestId; this.endpoint = endpoint;\n        }\n    }\n\n    public static List<String> affectedRequests(List<Ev> events) {\n        Set<String> seen = new HashSet<>();     // WRONG: HashSet scrambles first-appearance order\n        for (Ev e : events) {\n            if (e.level.equals(\"ERROR\")) seen.add(e.requestId);\n        }\n        return new ArrayList<>(seen);\n    }\n\n    public static Map<String, Long> byEndpoint(List<Ev> events) {\n        Map<String, Long> out = new HashMap<>();\n        for (Ev e : events) {                    // WRONG: counts ALL events, not errors\n            out.merge(e.endpoint, 1L, Long::sum);\n        }\n        return out;\n    }\n\n    public static List<String> cascadeOf(List<Ev> events, String requestId) {\n        return events.stream()\n            .filter(e -> e.level.equals(\"ERROR\"))   // WRONG: only errors \u2014 timeline loses context\n            .map(e -> e.event)\n            .collect(Collectors.toList());\n    }\n\n    public static String verdict(List<Ev> events) {\n        return \"widespread\";   // WRONG: one verdict for every incident\n    }\n\n    public static String refutes(String hypothesis) {\n        return \"unknown\";   // WRONG: unfalsifiable analysis\n    }\n}\n";
R["javaa-checkpoint-m15-task"] = "\nimport java.io.*;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.*;\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public interface Engine {\n        void put(String key, String value);\n        Optional<String> get(String key);\n        List<String> keys();\n        int count();\n    }\n\n    public static class InMemory implements Engine {\n        private final ConcurrentHashMap<String, String> data = new ConcurrentHashMap<>();\n        public void put(String key, String value) { data.put(key, value); }\n        public Optional<String> get(String key) { return Optional.ofNullable(data.get(key)); }\n        public List<String> keys() {\n            List<String> ks = new ArrayList<>(data.keySet());\n            Collections.sort(ks);\n            return ks;\n        }\n        public int count() { return data.size(); }\n    }\n\n    public static class JsonlFile implements Engine {\n        private final Path file;\n        private final ConcurrentHashMap<String, String> index = new ConcurrentHashMap<>();\n\n        JsonlFile(Path file) { this.file = file; }\n\n        public void put(String key, String value) {\n            try {\n                Files.writeString(file,\n                    \"{\\\"op\\\":\\\"put\\\",\\\"k\\\":\\\"\" + key + \"\\\",\\\"v\\\":\\\"\" + value + \"\\\"}\\n\",\n                    StandardCharsets.UTF_8, StandardOpenOption.CREATE, StandardOpenOption.APPEND);\n            } catch (IOException e) {\n                throw new UncheckedIOException(e);\n            }\n            index.put(key, value);\n        }\n\n        public Optional<String> get(String key) { return Optional.ofNullable(index.get(key)); }\n        public List<String> keys() {\n            List<String> ks = new ArrayList<>(index.keySet());\n            Collections.sort(ks);\n            return ks;\n        }\n        public int count() { return index.size(); }\n\n        void apply(String line) {\n            int k = line.indexOf(\"\\\"k\\\":\\\"\");\n            int v = line.indexOf(\"\\\"v\\\":\\\"\");\n            if (k >= 0 && v >= 0) {\n                int kEnd = line.indexOf(\"\\\"\", k + 5);\n                int vEnd = line.indexOf(\"\\\"\", v + 5);\n                index.put(line.substring(k + 5, kEnd), line.substring(v + 5, vEnd));\n            }\n        }\n    }\n\n    public static Engine replay(Path file) {\n        try {\n            JsonlFile e = new JsonlFile(file);\n            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {\n                e.apply(line);\n            }\n            return e;\n        } catch (IOException ex) {\n            throw new UncheckedIOException(ex);\n        }\n    }\n\n    public static class LedgerService {\n        private final Engine engine;\n\n        public LedgerService(Engine engine) { this.engine = engine; }\n\n        public String get(String key) {\n            return engine.get(key).orElse(\"MISSING\");\n        }\n\n        public void record(String key, String value) {\n            engine.put(key, value);\n        }\n\n        public List<String> entries() {\n            return engine.keys().stream()\n                .map(k -> k + \"=\" + engine.get(k).orElse(\"MISSING\"))\n                .collect(Collectors.toList());\n        }\n\n        public static String health(int count, int failures) {\n            if (failures != 0) return \"red\";\n            return count > 0 ? \"green\" : \"yellow\";\n        }\n    }\n\n    public static String report(LedgerService svc, List<String> keys, Executor exec) {\n        List<CompletableFuture<String>> parts = keys.stream()\n            .map(k -> CompletableFuture\n                .<String>supplyAsync(() -> k + \"=\" + svc.get(k), exec)\n                .orTimeout(50, TimeUnit.MILLISECONDS)\n                .handle((r, e) -> e == null ? r : k + \"=down\"))\n            .collect(Collectors.toList());\n        CompletableFuture.allOf(parts.toArray(new CompletableFuture[0]))\n            .orTimeout(500, TimeUnit.MILLISECONDS).join();\n        return parts.stream().map(CompletableFuture::join)\n            .collect(Collectors.joining(\",\"));\n    }\n\n    public static String prove(String seed) {\n        try {\n            Path file = Files.createTempFile(\"cjadv\", \".jsonl\");\n            LedgerService fileSvc = new LedgerService(new JsonlFile(file));\n            fileSvc.record(\"a\", \"1\");\n            fileSvc.record(\"b\", \"2\");\n            LedgerService memSvc = new LedgerService(new InMemory());\n            memSvc.record(\"a\", \"1\");\n            memSvc.record(\"b\", \"2\");\n            Executor exec = Executors.newVirtualThreadPerTaskExecutor();\n            String fromFile = report(fileSvc, List.of(\"a\", \"b\"), exec);\n            String fromMem = report(memSvc, List.of(\"a\", \"b\"), exec);\n            if (!seed.isEmpty()) { /* deterministic hook */ }\n            return fromFile + \"|\" + fromMem;\n        } catch (IOException e) {\n            throw new UncheckedIOException(e);\n        }\n    }\n\n    public static boolean survivesRestart(Path file) {\n        LedgerService original = new LedgerService(new JsonlFile(file));\n        original.record(\"x\", \"9\");\n        LedgerService restarted = new LedgerService(replay(file));\n        return restarted.get(\"x\").equals(\"9\");\n    }\n}\n";
W["javaa-checkpoint-m15-task"] = "\nimport java.io.*;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.*;\nimport java.util.*;\nimport java.util.concurrent.*;\nimport java.util.stream.*;\n\npublic class Solution {\n    public interface Engine {\n        void put(String key, String value);\n        Optional<String> get(String key);\n        List<String> keys();\n        int count();\n    }\n\n    public static class InMemory implements Engine {\n        private final ConcurrentHashMap<String, String> data = new ConcurrentHashMap<>();\n        public void put(String key, String value) { data.put(key, value); }\n        public Optional<String> get(String key) { return Optional.ofNullable(data.get(key)); }\n        public List<String> keys() {\n            List<String> ks = new ArrayList<>(data.keySet());   // WRONG: unsorted\n            return ks;\n        }\n        public int count() { return data.size(); }\n    }\n\n    public static class JsonlFile implements Engine {\n        private final Path file;\n        private final ConcurrentHashMap<String, String> index = new ConcurrentHashMap<>();\n\n        JsonlFile(Path file) { this.file = file; }\n\n        public void put(String key, String value) {\n            index.put(key, value);   // WRONG: writes nothing to disk\n        }\n\n        public Optional<String> get(String key) { return Optional.ofNullable(index.get(key)); }\n        public List<String> keys() { return new ArrayList<>(index.keySet()); }   // WRONG: unsorted\n        public int count() { return index.size(); }\n    }\n\n    public static Engine replay(Path file) {\n        return new JsonlFile(file);   // WRONG: empty state \u2014 history lost\n    }\n\n    public static class LedgerService {\n        private final Engine engine;\n\n        public LedgerService(Engine engine) { this.engine = engine; }\n\n        public String get(String key) {\n            return engine.get(key).orElse(\"MISSING\");\n        }\n\n        public void record(String key, String value) {\n            engine.put(key, value);\n        }\n\n        public List<String> entries() {\n            return engine.keys().stream()\n                .map(k -> k + \"=\" + engine.get(k))\n                .collect(Collectors.toList());\n        }\n\n        public static String health(int count, int failures) {\n            return \"green\";   // WRONG: health that lies\n        }\n    }\n\n    public static String report(LedgerService svc, List<String> keys, Executor exec) {\n        StringBuilder sb = new StringBuilder();   // WRONG: sequential loop, no bounds,\n        for (String k : keys) {                    // no recovery \u2014 a hung read hangs the report\n            sb.append(k).append(\"=\").append(svc.get(k)).append(\",\");\n        }\n        if (sb.length() > 0) sb.setLength(sb.length() - 1);\n        return sb.toString();\n    }\n\n    public static String prove(String seed) {\n        try {\n            Path file = Files.createTempFile(\"cjadv\", \".jsonl\");\n            LedgerService fileSvc = new LedgerService(new JsonlFile(file));\n            fileSvc.record(\"a\", \"1\");\n            fileSvc.record(\"b\", \"2\");\n            LedgerService memSvc = new LedgerService(new InMemory());\n            memSvc.record(\"a\", \"1\");\n            memSvc.record(\"b\", \"2\");\n            Executor exec = Executors.newVirtualThreadPerTaskExecutor();\n            return report(fileSvc, List.of(\"a\", \"b\"), exec) + \"|\" +\n                   report(memSvc, List.of(\"a\", \"b\"), exec);\n        } catch (IOException e) {\n            throw new UncheckedIOException(e);\n        }\n    }\n\n    public static boolean survivesRestart(Path file) {\n        LedgerService original = new LedgerService(new JsonlFile(file));\n        original.record(\"x\", \"9\");\n        LedgerService restarted = new LedgerService(replay(file));\n        return restarted.get(\"x\").equals(\"9\");\n    }\n}\n";
